schema:
CREATE TABLE Bar (
    name VARCHAR NOT NULL,
    address VARCHAR NOT NULL,
    PRIMARY KEY (name)
);

CREATE TABLE Beer (
    name VARCHAR NOT NULL,
    brewer VARCHAR NOT NULL,
    PRIMARY KEY (name)
);

CREATE TABLE Drinker (
    name VARCHAR NOT NULL,
    address VARCHAR NOT NULL,
    PRIMARY KEY (name)
);

CREATE TABLE Frequents (
    drinker VARCHAR NOT NULL,
    bar VARCHAR NOT NULL,
    times_a_week SMALLINT NOT NULL,
    PRIMARY KEY (drinker, bar),
    FOREIGN KEY (drinker) REFERENCES Drinker(name),
    FOREIGN KEY (bar) REFERENCES Bar(name)
);

CREATE TABLE Serves (
    bar VARCHAR NOT NULL,
    beer VARCHAR NOT NULL,
    price DECIMAL(5,2) NOT NULL,
    PRIMARY KEY (bar, beer),
    FOREIGN KEY (bar) REFERENCES Bar(name),
    FOREIGN KEY (beer) REFERENCES Beer(name)
);

CREATE TABLE Likes (
    drinker VARCHAR NOT NULL,
    beer VARCHAR NOT NULL,
    PRIMARY KEY (drinker, beer),
    FOREIGN KEY (drinker) REFERENCES Drinker(name),
    FOREIGN KEY (beer) REFERENCES Beer(name)
);

counterexample:
INSERT INTO Drinker (name, address) VALUES ('Alice', '123 Main St');
INSERT INTO Drinker (name, address) VALUES ('Bob', '456 Oak Ave');
INSERT INTO Bar (name, address) VALUES ('PubA', '789 Elm St');
INSERT INTO Beer (name, brewer) VALUES ('Lager', 'BrewCo');
INSERT INTO Beer (name, brewer) VALUES ('Stout', 'BrewCo');
INSERT INTO Frequents (drinker, bar, times_a_week) VALUES ('Bob', 'PubA', 3);
INSERT INTO Serves (bar, beer, price) VALUES ('PubA', 'Lager', 5.00);
INSERT INTO Serves (bar, beer, price) VALUES ('PubA', 'Stout', 5.50);
INSERT INTO Likes (drinker, beer) VALUES ('Bob', 'Lager');

