INSERT INTO Drinker (name, address) VALUES ('Alice', '456 Oak Ave');
INSERT INTO Frequents (drinker, bar, times_a_week) VALUES ('Alice', 'BarA', 5);
INSERT INTO Serves (bar, beer, price) VALUES ('BarA', 'Corona', 4.00);

